    (bv_unsigned b0 + Z.of_nat (length bs0) <= 2 ^ 47)%Z ->
    (bv_unsigned b1 + Z.of_nat (length bs1) <= su - 112 \/ su <= bv_unsigned b1)%Z ->
    (bv_unsigned b1 + Z.of_nat (length bs1) <= 2 ^ 47)%Z ->
