  Lemma stack_ok_of_window : forall vals ebs M kn so,
    let E := Env (vals_ev vals) ebs in
    know_ok RSEGS E M kn -> has_window kn = true ->
    vals_ev vals 0 = sp0 ->
    - 2 ^ 22 <= so <= 0 -> so mod 16 = 0 ->
    stack_ok L M (bv_unsigned sp0 + so).
