  (* [comment removed for export] *)
  Definition CPstk (a : Z) : Prop := a < 4096 \/ (0x10000 <= a < 0xfa000) \/ bv_unsigned sp0 - 8388608 <= a.

  Lemma regions_stk : forall vals ebs,
    let E := Env (vals_ev vals) ebs in
    vals_ev vals 0 = sp0 ->
